    {
        $this->visible($request, $ticket, $access);

        return new PortalTicketAttachmentApiResource($this->publicAttachments($ticket)->findOrFail($attachment));
    }

    #[OA\Get(path: '/api/v1/portal/tickets/{ticket}/attachments/{attachment}/download', operationId: 'ticketPortalTicketApiControllerdownload', security: [['bearerAuth' => []]], tags: ['Tickets'], parameters: [new OA\Parameter(name: 'ticket', in: 'path', required: true, schema: new OA\Schema(type: 'string')), new OA\Parameter(name: 'attachment', in: 'path', required: true, schema: new OA\Schema(type: 'integer')), new OA\Parameter(name: 'membership_id', in: 'query', required: false, description: 'Select one of this customer identity active memberships; an invalid identifier never falls back to another customer.', schema: new OA\Schema(type: 'integer', minimum: 1))], x: ['required-scopes' => ['portal.tickets.attachments.download'], 'domain-permissions' => 'active_customer_portal_membership', 'additional-domain-permissions' => []], responses: [new OA\Response(response: 200, description: 'Explicit persisted read-back or preview', content: new OA\MediaType(mediaType: 'application/octet-stream', schema: new OA\Schema(type: 'string', format: 'binary'))), new OA\Response(response: 401, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 403, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 404, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError')), new OA\Response(response: 422, description: 'Authorization, ownership or validation failure', content: new OA\JsonContent(ref: '#/components/schemas/ParityReadError'))])]
    public function download(Request $request, Ticket $ticket, int $attachment, PortalTicketAccess $access)
    {
        $this->visible($request, $ticket, $access);
        $file = $this->publicAttachments($ticket)->findOrFail($attachment);
        $disk = $file->disk ?: 'local';
        abort_unless($file->path && Storage::disk($disk)->exists($file->path), 404);

        return Storage::disk($disk)->download($file->path, basename(str_replace('\\', '/', $file->filename)));
    }

    private function visible(Request $request, Ticket $ticket, PortalTicketAccess $access): void
    {
        abort_unless($access->canView($request->attributes->get('customerPortalContext'), $ticket), 404);
    }

    private function publicAttachments(Ticket $ticket)
    {
        return TicketAttachment::query()->where('ticket_id', $ticket->id)->whereHas('message', fn ($q) => $q->where('ticket_id', $ticket->id)->where('visibility', 'public'));
    }

    private function validateInput(Request $request, array $rules): array
    {
        return \App\Modules\Integration\Support\DomainApiInput::validate($request, $rules, ['membership_id']);
    }
}
